def verify_convex_polygon(
    x_commitment: PedersenCommitment,
    y_commitment: PedersenCommitment,
    polygon: ConvexPolygonRegion,
    proof: ConvexPolygonRegionProof,
    context: bytes = b"",
) -> bool:
    """Verify a :class:`ConvexPolygonRegionProof` against public inputs only.

    The verifier needs just the two commitments, the polygon, the proof and
    the context — never the coordinates or blinding factors. Type errors
    (wrong object or field types at any nesting level, including a ``bool``
    integer or a non-``bytes`` context) raise :class:`TypeError`; every
    semantic failure — mismatched group parameters or declared ranges, a
    tampered proof field, a forged proof, a different polygon, commitment or
    context, or swapped axes — returns ``False``. Inputs are never mutated.
    """
    if not isinstance(x_commitment, PedersenCommitment):
        raise TypeError("x_commitment must be a PedersenCommitment")
    if not isinstance(y_commitment, PedersenCommitment):
        raise TypeError("y_commitment must be a PedersenCommitment")
    _check_commitment_fields(x_commitment)
    _check_commitment_fields(y_commitment)
    if not isinstance(polygon, ConvexPolygonRegion):
        raise TypeError("polygon must be a ConvexPolygonRegion")
    if not isinstance(proof, ConvexPolygonRegionProof):
        raise TypeError("proof must be a ConvexPolygonRegionProof")
    if not isinstance(proof.x_proof, RangeProof):
        raise TypeError("proof x_proof must be a RangeProof")
    if not isinstance(proof.y_proof, RangeProof):
        raise TypeError("proof y_proof must be a RangeProof")
    if not isinstance(proof.edge_proofs, tuple):
        raise TypeError("proof edge_proofs must be a tuple of WideRangeProof")
    for edge_proof in proof.edge_proofs:
        if not isinstance(edge_proof, WideRangeProof):
            raise TypeError("proof edge_proofs entries must be WideRangeProof")
    _check_bytes(context, "context")
    if (
        x_commitment.prime != y_commitment.prime
        or x_commitment.generator != y_commitment.generator
        or x_commitment.h != y_commitment.h
    ):
        return False
    if (x_commitment.lower, x_commitment.upper) != (polygon.min_x, polygon.max_x):
        return False
    if (y_commitment.lower, y_commitment.upper) != (polygon.min_y, polygon.max_y):
        return False
    if len(proof.edge_proofs) != len(polygon.vertices):
        return False
    if (polygon.max_x - polygon.min_x + 1) > _MAX_RANGE_VALUES:
        return False
    if (polygon.max_y - polygon.min_y + 1) > _MAX_RANGE_VALUES:
        return False
    items = _polygon_transcript_items(context, polygon, x_commitment, y_commitment)
    if not verify_range(
        x_commitment,
        proof.x_proof,
        _polygon_sub_context(b"bbox-x", items),
    ):
        return False
    if not verify_range(
        y_commitment,
        proof.y_proof,
        _polygon_sub_context(b"bbox-y", items),
    ):
        return False
    prime = x_commitment.prime
    for edge_index, edge in enumerate(polygon._interior_edges()):
        offset_upper = _edge_offset_upper(polygon, edge)
        width = max(1, offset_upper.bit_length())
        if width > _MAX_WIDE_RANGE_BITS:
            return False
        edge_upper = (1 << width) - 1
        if edge_upper >= prime - 1:
            return False
        edge_commitment = _edge_commitment(
            x_commitment, y_commitment, edge, edge_upper
        )
        edge_items = [*items, str(edge_index).encode("ascii")]
        if not verify_range_wide(
            edge_commitment,
            proof.edge_proofs[edge_index],
            _polygon_sub_context(b"edge", edge_items),
        ):
            return False
    return True


@dataclass(frozen=True)
class ConvexPolygonBatchEntry:

def _wide_range_replay_digest(
    entry: WideRangeBatchEntry,
    session_id: bytes,
    expires_at: int | None,
) -> bytes:
    """Compute ``SHA-256(F(D) || F(session_id) || L(entry) || F(E))``."""
    transcript = hashlib.sha256()
    transcript.update(len(_WIDE_RANGE_REPLAY_DOMAIN).to_bytes(4, "big"))
    transcript.update(_WIDE_RANGE_REPLAY_DOMAIN)
    transcript.update(len(session_id).to_bytes(4, "big"))
    transcript.update(session_id)
    transcript.update(_bound_wide_range_leaf(entry))  # raw leaf, no F framing
    expiry = _replay_expiry_bytes(expires_at)
    transcript.update(len(expiry).to_bytes(4, "big"))
    transcript.update(expiry)
    return transcript.digest()


def _check_wide_range_batch_entry(
    entry: object, name: str = "entry"
) -> WideRangeBatchEntry:
    """Validate one WideRangeBatchEntry and its nested field types."""
    if not isinstance(entry, WideRangeBatchEntry):
        raise TypeError(f"{name} must be a WideRangeBatchEntry")
    commitment = entry.commitment
    if not isinstance(commitment, PedersenCommitment):
        raise TypeError(f"{name} commitment must be a PedersenCommitment")
    _check_commitment_fields(commitment)
    proof = entry.proof
    if not isinstance(proof, WideRangeProof):
        raise TypeError(f"{name} proof must be a WideRangeProof")
    if not isinstance(proof.commitments, tuple):
        raise TypeError(
            f"{name} proof commitments must be a tuple of integers"
        )
    for item in proof.commitments:
        _check_int(item, f"{name} proof commitments entry")
    for field_name in ("challenges", "responses"):
        field = getattr(proof, field_name)
        if not isinstance(field, tuple):
            raise TypeError(
                f"{name} proof {field_name} must be a tuple of integer pairs"
            )
        for pair in field:
            if not isinstance(pair, tuple):
                raise TypeError(
                    f"{name} proof {field_name} entry must be a tuple of integers"
                )
            for item in pair:
                _check_int(item, f"{name} proof {field_name} entry item")
    _check_bytes(entry.context, f"{name} context")
    return entry


class WideRangeReplayGuard:
    """Single-use replay protection for one wide range batch entry.

    A fresh guard has no registrations. :meth:`bind_once` registers a pending
    :class:`ReplayBinding` for a single :class:`WideRangeBatchEntry`;
    :meth:`check` accepts an equal pending binding exactly once and then
    marks the id consumed. By default both the pending and the consumed
    state live on this guard instance and are never shared between
    instances; passing an :class:`SQLiteReplayStore` as ``store`` instead
    keeps the state in that store under the ``b"zr/wrr/v1"`` key domain, so
    guards attached to the same store namespace share pending, claimed and
    consumed ids across independent instances, processes and restarts.

    The binding digest reuses the single-entry guard framing of
    :class:`RangeReplayGuard` byte for byte (``F(D) || F(session_id) ||
    L(entry) || F(E)``), differing only in the domain separator
    (``b"zr/wrr/v1"``, which doubles as the store row-key domain) and in
    ``L(entry)``: the raw per-item outer leaf bytes of a complete wide
    range batch (:func:`_bound_wide_range_leaf`, the existing outer leaf
    encoding under ``b"zkregion/wrb/v1"``).

    As with :class:`RangeReplayGuard`, concurrent checks of the same id are
    decided by an atomic claim taken before the digest/expiry work and the
    potentially slow wide range verification (the in-instance registry
    lock, or the store's short transaction and unique claim token); the
    verification runs without any lock or transaction held, so different
    ids are never serialized.
    """

    def __init__(self, *, store: SQLiteReplayStore | None = None) -> None:
        if store is not None and not isinstance(store, SQLiteReplayStore):
            raise TypeError("store must be an SQLiteReplayStore")
        self._store = (
            None if store is None else store._view(_WIDE_RANGE_REPLAY_DOMAIN)
        )
        self._registry = None if store is not None else _ReplayRegistry()

    @property
    def _pending(self) -> dict[bytes, ReplayBinding]:
        if self._store is not None:
            return self._store.pending_snapshot()
        return self._registry.pending_snapshot()

    @property
    def _consumed(self) -> set[bytes]:
        if self._store is not None:
            return self._store.consumed_snapshot()
        return self._registry.consumed_snapshot()

    def bind_once(
        self,
        entry: WideRangeBatchEntry,
        session_id: bytes,
        *,
        expires_at: int | None = None,
    ) -> ReplayBinding:
        """Register this instance's binding of ``session_id`` to ``entry``.

        Returns the frozen :class:`ReplayBinding`. ``session_id`` must be
        non-empty ``bytes`` and ``expires_at`` must be either ``None`` or a
        non-``bool`` unsigned 64-bit Unix-second timestamp. A session id
        that is already pending, being checked or has been consumed raises
        :class:`ValueError`; wrong argument or nested field types
        (including ``bool`` integers) raise :class:`TypeError` (an empty id
        or an out-of-range expiry raises :class:`ValueError`). Inputs are
        never mutated.

